-- Demo data, generated once from the clickable demo. Loaded in demo mode only.
create or replace function app.rel(ms bigint) returns timestamptz language sql stable as $$ select app.now() + make_interval(secs => ms / 1000.0) $$;
-- tomorrow at 12:00 in Nigeria, and so on
create or replace function app.wat_at(day_off int, hh int, mm int) returns timestamptz language sql stable as $$
  select ((date_trunc('day', app.wat(app.now())) + make_interval(days => day_off, hours => hh, mins => mm)) - interval '1 hour') at time zone 'UTC'
$$;

create or replace function app.seed_demo() returns void language plpgsql as $seed$
begin
update app.settings set demo = true, shift_ms = 0;

perform app.update_trust(id) from app.agents;
end $seed$;
